    back.appendChild(cap);
    back.appendChild(close);
    back.addEventListener("click", () => this.closeCopyOverlay());
    document.body.appendChild(back);
    this.copyOverlay = back;
    inp.focus();
    inp.select();
    inp.setSelectionRange(0, link.length);
